using System;using System.IO;using System.Linq;using System.Collections;using System.Reflection;using BepInEx;using BepInEx.Unity.Mono;using UnityEngine;using InFalsusStudio;using InFalsusStudio.Core;using InFalsusStudio.Gameplay;using InFalsusStudio.NativeEditorUI;
[BepInPlugin("test.skyarea.spc2","SPC2 SkyArea checks","1.0.0")]
public class SkyChecks:BaseUnityPlugin {
 string root=@"E:\RhythmGame\InFalsusStudio+\feature_work\skyarea-spc2";int count,failures;
 void Check(bool ok,string name){count++;File.AppendAllText(root+"/checks.txt",(ok?"PASS ":"FAIL ")+name+"\n");if(!ok)failures++;}
 static NativeJudgeEngine Engine(string body,double entry=1000){return new NativeJudgeEngine(SpcDocument.Parse("chart(120,4)\n"+body).ReadEvents(),entry);}
 static GameplayInputSampler Input(double x){var i=new GameplayInputSampler();i.Move(1000,x);i.Move(1000,x);return i;}
 static void Step(NativeJudgeEngine e,GameplayInputSampler i,double t,double x){i.Move(t,x);e.Step(t,i);}
 const string Narrow="skyarea(1000,50,100,20,50,100,20,0,0,2000,7)\n";
 void Logic(){
  var e=Engine(Narrow);var i=Input(.5);Step(e,i,1000,.5);var g=e.SkyGroupsById.Values.Single();Check(g.Ready&&g.Current.Capacity==300,"initial capture");Step(e,i,1050,.9);Check(g.Ready&&g.Current.Capacity==200&&g.Current.Cooldown==0,"50ms departure keeps capture and consumes 100");Check(Math.Abs(g.Red-1f/9)<.00001,"50ms departure produces native squared red factor");Step(e,i,1075,.5);Check(g.Current.Capacity==225&&g.Red==0,"re-entry restores gradually and red cutoff is exact");Step(e,i,1225,.9);Check(g.Current.Capacity==0&&g.Current.Cooldown==500&&!g.Ready,"exhaustion starts full cooldown at sample");double frontier=g.ClipUntil;Step(e,i,1325,.5);Check(g.Current.Cooldown==400&&!g.Ready&&g.ClipUntil==frontier,"cooldown freezes clip frontier and feedback");Step(e,i,1725,.5);Check(g.Current.Capacity==300&&g.Current.Cooldown==0&&g.Ready,"cooldown ends with full capacity and re-capture");
  var b=new SkyBudget{Time=100,Capacity=20,Captured=true};SkyBudget.Advance(ref b,130,0);Check(b.Cooldown==500&&b.Capacity==0,"new cooldown is not backdated within dt");SkyBudget.Advance(ref b,630,1);Check(b.Cooldown==0&&b.Capacity==300&&b.Captured,"exact cooldown expiry captures");double before=b.Time;SkyBudget.Advance(ref b,600,0);Check(b.Time==before&&b.Capacity==300,"backwards sample cannot refill or consume");b.Capacity=100;SkyBudget.Advance(ref b,730,2);Check(b.Capacity==100,"inactive group does not consume capacity");
  string twins="skyarea(1000,25,100,10,25,100,10,0,0,1000,9)\nskyarea(1000,75,100,10,75,100,10,0,0,1000,9)\n";e=Engine(twins);i=Input(.25);Step(e,i,1000,.25);Step(e,i,1250,.25);g=e.SkyGroupsById.Values.Single();Check(e.ExactPlus==2&&g.Current.Capacity==300,"disjoint same-group members use union and independent ticks");Check(e.Notes.All(n=>e.SkyActive(n.Source.SourceId)),"all same-group members share valid capture");
  e=Engine(twins.Replace("1000,9)\n","1000,8)\n").Replace("75,100,10,0,0,1000,8)","75,100,10,0,0,1000,3)"));i=Input(.25);Step(e,i,1000,.25);Step(e,i,1150,.25);Check(e.SkyGroupsById.Count==2,"distinct groups remain independent regardless numeric order");Check(e.SkyState(e.Notes[0].Source.SourceId).Ready&&!e.SkyState(e.Notes[1].Source.SourceId).Ready,"one group cooldown cannot break another");
  e=Engine(Narrow);i=Input(.9);Step(e,i,1000,.9);Step(e,i,1100,.9);Step(e,i,1250,.5);var g0=e.SkyGroupsById.Values.Single();var committed=g0.Current;int settled=e.Settled;for(int n=0;n<20;n++)g0.Judge(e.Notes[0],1250,.5);Check(g0.Current.Time==committed.Time&&g0.Current.Capacity==committed.Capacity&&g0.Current.Cooldown==committed.Cooldown&&e.Settled==settled,"event replays never mutate committed budget or score");
  e=Engine(Narrow);i=Input(.5);Step(e,i,1000,.5);Step(e,i,1200,.5);Step(e,i,1250,.9);Check(e.ExactPlus==1,"tick during short departure remains Exact+");
  var members=SpcDocument.Parse("chart(120,4)\nskyarea(1000,25,100,10,25,100,10,0,0,500,4)\nskyarea(1500,50,100,100,50,100,100,0,0,500,4)\n").ReadEvents();e=new NativeJudgeEngine(members,1000);i=Input(.9);Step(e,i,1000,.9);var seam=e.SkyGroupsById.Values.Single();seam.Current=new SkyBudget{Time=1490,Capacity=100,Captured=false};Step(e,i,1500,.9);Check(e.Notes[0].Ticks.Last().Candidate==1,"new wide segment cannot redeem finishing interval across seam");
  e=Engine(Narrow);i=Input(.5);Step(e,i,1000,.5);Step(e,i,1050,.9);g=e.SkyGroupsById.Values.Single();double cap=g.Current.Capacity;Step(e,i,1050,.9);Check(g.Current.Capacity==cap,"same-time repeated update does not double drain");g.Current.Captured=false;Step(e,i,1050,.5);Check(g.Current.Captured&&g.Current.Capacity==cap,"same-time cursor change can recapture without refilling");
  string auto="skyarea(1000,25,100,10,25,100,10,0,0,500,10)\n"+"skyarea(1500,75,100,10,75,100,10,0,0,500)\n";var original=SpcDocument.Parse("chart(120,4)\n"+auto);string bytes=original.ToString();e=new NativeJudgeEngine(original.ReadEvents(),1000);Check(e.SkyGroupsById.Count==1,"automatic sky grouping matches SPC2 chronological join even across disjoint geometry");Check(original.ReadEvents().Last().Args.Length==10,"runtime grouping leaves source optional arguments unchanged");
  Check(NativeJudgeEngine.Grade(25)==6&&NativeJudgeEngine.Grade(50)==5&&NativeJudgeEngine.Grade(100)==3,"ground grade windows unchanged");Check(NativeJudgeEngine.Grade(50,true)==6&&NativeJudgeEngine.Grade(100,true)==5&&NativeJudgeEngine.Grade(200,true)==3,"Flick grade windows unchanged");
  e=Engine("tap(1000,1,1)\n");i=Input(.5);i.SetLane(1,true,1000);e.Step(1000,i);Check(e.ExactPlus==1&&e.Combo==1,"ground tap scoring still independent of sky groups");
  e=Engine(Narrow);i=Input(.9);Step(e,i,1000,.9);Step(e,i,1150,.9);Step(e,i,1250,.9);var gauge=e.GetType().GetField("Gauge",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(gauge!=null)Check(e.Break==1&&Math.Abs((double)gauge.GetValue(e)-14)<.000001,"SPC2 sky Break feeds the merged live gauge once");
  e=Engine("timinggroup(hidden):\nhidegroup(0,1)\n"+Narrow+"groupend()\n");Check(InFalsusStudio.TimeGroups.TimingGroups.Hidden(e.Notes[0].Source,1250),"runtime Sky clones retain hidegroup metadata for contact feedback");
  var regions=new System.Collections.Generic.List<InFalsusStudio.NativeVisual.NativeSkyFeedback.Region>{new InFalsusStudio.NativeVisual.NativeSkyFeedback.Region(.2,.3,1000,2000),new InFalsusStudio.NativeVisual.NativeSkyFeedback.Region(.7,.8,1000,2000)};
  Check(InFalsusStudio.NativeVisual.NativeSkyFeedback.Contains(regions,.25,1250)&&InFalsusStudio.NativeVisual.NativeSkyFeedback.Contains(regions,.75,1250)&&!InFalsusStudio.NativeVisual.NativeSkyFeedback.Contains(regions,.5,1250),"contact emission covers both disjoint members without lighting the gap");
  Check(!InFalsusStudio.NativeVisual.NativeSkyFeedback.Contains(regions,.25,2000),"contact emission stops at native exclusive end");
  Color red=SkyGameplayPalette.Blend(SkyGameplayPalette.Edge,SkyGameplayPalette.EdgeRed,1);Check(red==SkyGameplayPalette.EdgeRed&&red.r>3,"red endpoint preserves HDR");Check(SkyGameplayPalette.Blend(SkyGameplayPalette.Main,SkyGameplayPalette.MainRed,0)==SkyGameplayPalette.Main,"purple endpoint exact");Check(Math.Abs(SkyGameplayPalette.Blend(SkyGameplayPalette.Back,SkyGameplayPalette.BackRed,.5f).a-(SkyGameplayPalette.Back.a+SkyGameplayPalette.BackRed.a)*.5f)<.000001,"Oklab blend preserves native alpha interpolation");
 }
 IEnumerator Start(){if(!Environment.GetCommandLineArgs().Contains("-sky-spc2-checks"))yield break;File.WriteAllText(root+"/checks.txt","SPC2 sky checks\n");yield return new WaitForSeconds(5);try{Logic();}catch(Exception ex){File.AppendAllText(root+"/checks.txt","FAIL exception "+ex+"\n");failures++;}
  var ui=NativeEditorUIPlugin.I;var boot=ui.boot;var f=NativeEditorUIPlugin.F;foreach(string name in new[]{"showReleaseNotes","guiShowReleaseNotes"})NativeEditorUIPlugin.Set(boot,name,false);
  var doc=SpcDocument.Parse("chart(120,4)\nskyarea(1000,50,100,30,50,100,30,0,0,5000,2)\n");var method=typeof(StudioBootstrap).GetMethod("LoadDocument",f);var ps=method.GetParameters();var args=new object[ps.Length];args[0]=doc;for(int n=1;n<args.Length;n++)args[n]=ps[n].DefaultValue;method.Invoke(boot,args);NativeEditorUIPlugin.Set(boot,"showNotes",true);var tr=NativeEditorUIPlugin.Val<StudioTransport>(boot,"transport");tr.Seek(1000);Check(GameplaySession.Enter(boot),"real gameplay session starts with SPC2 engine");GameplaySession.Phase=GameplayPhase.Playing;tr.Pause();GameplaySession.Now=1500;var eng=GameplaySession.Engine;var input=GameplaySession.InputState;Step(eng,input,1000,.5);Step(eng,input,1050,.5);Step(eng,input,1200,.9);GameplaySession.Now=1200;Check(eng.SkyGroupsById.Values.Single().Red==1,"fully red group state");Check(Math.Abs(GameplaySession.SkyClipBegin(eng.Notes[0].Source.TimeMs,1500,eng.Notes[0].Source)-1050)<.01,"lost capture freezes actual renderer begin time");// Freeze the real-session driver before yielding; only the deterministic trace advances judgement.
  GameplaySession.Phase=GameplayPhase.LeadIn;GameplaySession.LeadDeadline=Time.realtimeSinceStartupAsDouble+100;GameplaySession.Now=1200;
  yield return new WaitForEndOfFrame();bool saw=false;foreach(var renderer in Resources.FindObjectsOfTypeAll<MeshRenderer>()){var mat=renderer.sharedMaterial;if(!mat||!mat.HasProperty("_Color")||!renderer.gameObject.name.StartsWith("NativeVisual sky-"))continue;var color=mat.GetColor("_Color");if(Math.Abs(color.r-SkyGameplayPalette.MainRed.r)<.001)saw=true;}Check(saw,"actual SkyArea material reaches native red palette");ScreenCapture.CaptureScreenshot(root+"/red.png");yield return new WaitForSeconds(.2f);GameplaySession.Exit();Check(!GameplaySession.Active&&Math.Abs(tr.TimeMs-1000)<.01,"exit restores entry time");yield return null;yield return new WaitForEndOfFrame();bool purple=false;foreach(var renderer in Resources.FindObjectsOfTypeAll<MeshRenderer>()){var mat=renderer.sharedMaterial;if(mat&&mat.HasProperty("_Color")&&renderer.gameObject.name.StartsWith("NativeVisual sky-")&&Math.Abs(mat.GetColor("_Color").r-SkyGameplayPalette.Main.r)<.001)purple=true;}Check(purple,"exit clears gameplay red palette in editing");File.AppendAllText(root+"/checks.txt","DONE checks="+count+" failures="+failures+"\n");Application.Quit();}
}
